`include "timescale.v"

module tst_bench_top();

// === Global Sync Signal ===
reg llm_go_signal = 1;


	//
	// wires && regs
	//
	reg  clk;
	reg instrument_clk; // instrumentation clock cycle
	reg  rstn;

	wire [31:0] adr;
	wire [ 7:0] dat_i, dat_o, dat0_i, dat1_i;
	wire we;
	wire stb;
	wire cyc;
	wire ack;
	wire inta;

	reg [7:0] q, qq;

	wire scl, scl0_o, scl0_oen, scl1_o, scl1_oen;
	wire sda, sda0_o, sda0_oen, sda1_o, sda1_oen;

	parameter PRER_LO = 3'b000;
	parameter PRER_HI = 3'b001;
	parameter CTR     = 3'b010;
	parameter RXR     = 3'b011;
	parameter TXR     = 3'b011;
	parameter CR      = 3'b100;
	parameter SR      = 3'b100;

	parameter TXR_R   = 3'b101; // undocumented / reserved output
	parameter CR_R    = 3'b110; // undocumented / reserved output

	parameter RD      = 1'b1;
	parameter WR      = 1'b0;
	parameter SADR    = 7'b0010_000;

	//
	// Module body
	//

	// generate clock
	always #5 clk = ~clk;
	always #20 instrument_clk = ~instrument_clk;

	integer f;
	// possible outputs: adr[31],adr[30],adr[29],adr[28],adr[27],adr[26],adr[25],adr[24],adr[23],adr[22],adr[21],adr[20],adr[19],adr[18],adr[17],adr[16],adr[15],adr[14],adr[13],adr[12],adr[11],adr[10],adr[9],adr[8],adr[7],adr[6],adr[5],adr[4],adr[3],adr[2],adr[1],adr[0],,dat_o[7],dat_o[6],dat_o[5],dat_o[4],dat_o[3],dat_o[2],dat_o[1],dat_o[0],cyc,stb,we,sda

	// hookup wishbone master model
	wb_master_model #(8, 32) u0 (
		.clk(clk),
		.rst(rstn),
		.adr(adr),
		.din(dat_i),
		.dout(dat_o),
		.cyc(cyc),
		.stb(stb),
		.we(we),
		.sel(),
		.ack(ack),
		.err(1'b0),
		.rty(1'b0)
	);

	wire stb0 = stb & ~adr[3];
	wire stb1 = stb &  adr[3];

	assign dat_i = ({{8'd8}{stb0}} & dat0_i) | ({{8'd8}{stb1}} & dat1_i);

	// hookup wishbone_i2c_master core
	i2c_master_top i2c_top (

		// wishbone interface
		.wb_clk_i(clk),
		.wb_rst_i(1'b0),
		.arst_i(rstn),
		.wb_adr_i(adr[2:0]),
		.wb_dat_i(dat_o),
		.wb_dat_o(dat0_i),
		.wb_we_i(we),
		.wb_stb_i(stb0),
		.wb_cyc_i(cyc),
		.wb_ack_o(ack),
		.wb_inta_o(inta),

		// i2c signals
		.scl_pad_i(scl),
		.scl_pad_o(scl0_o),
		.scl_padoen_o(scl0_oen),
		.sda_pad_i(sda),
		.sda_pad_o(sda0_o),
		.sda_padoen_o(sda0_oen)
	),
	i2c_top2 (

		// wishbone interface
		.wb_clk_i(clk),
		.wb_rst_i(1'b0),
		.arst_i(rstn),
		.wb_adr_i(adr[2:0]),
		.wb_dat_i(dat_o),
		.wb_dat_o(dat1_i),
		.wb_we_i(we),
		.wb_stb_i(stb1),
		.wb_cyc_i(cyc),
		.wb_ack_o(ack),
		.wb_inta_o(inta),

		// i2c signals
		.scl_pad_i(scl),
		.scl_pad_o(scl1_o),
		.scl_padoen_o(scl1_oen),
		.sda_pad_i(sda),
		.sda_pad_o(sda1_o),
		.sda_padoen_o(sda1_oen)
	);


	// hookup i2c slave model
	i2c_slave_model #(SADR) i2c_slave (
		.scl(scl),
		.sda(sda)
	);

        // create i2c lines
	delay m0_scl (scl0_oen ? 1'bz : scl0_o, scl),
	      m1_scl (scl1_oen ? 1'bz : scl1_o, scl),
	      m0_sda (sda0_oen ? 1'bz : sda0_o, sda),
	      m1_sda (sda1_oen ? 1'bz : sda1_o, sda);

	pullup p1(scl); // pullup scl line
	pullup p2(sda); // pullup sda line

	initial begin
		f = $fopen("output_tst_bench_top_t1.txt");
		$fwrite(f, "time,wb_dat_o[7],wb_dat_o[6],wb_dat_o[5],wb_dat_o[4],wb_dat_o[3],wb_dat_o[2],wb_dat_o[1],wb_dat_o[0],wb_ack_o,wb_inta_o,scl_pad_o,scl_padoen_o\n");
		// $fwrite(f, "wb_dat_o[0]\n");

		forever begin
			//@(posedge clk);
			//#200
			#1
			$fwrite(f, "%0d,%b,%b,%b,%b,%b,%b,%b,%b,%b,%b,%b,%b\n", 
			$time,dat0_i[7],dat0_i[6],dat0_i[5],dat0_i[4],dat0_i[3],dat0_i[2],dat0_i[1],dat0_i[0],ack,inta,scl0_o,scl0_oen);
			// $fwrite(f, "%0d,%b\n", 
			// $time,dat0_i[0]);
		end
	end

	initial begin
	      `ifdef WAVES
	         $shm_open("waves");
	         $shm_probe("AS",tst_bench_top,"AS");
	         $display("INFO: Signal dump enabled ...\n\n");
	      `endif

//	      force i2c_slave.debug = 1'b1; // enable i2c_slave debug information
	      force i2c_slave.debug = 1'b0; // disable i2c_slave debug information

	      $display("\nstatus: %t Testbench started\n\n", $time);

//	      $dumpfile("bench.vcd");
//	      $dumpvars(1, tst_bench_top);
//	      $dumpvars(1, tst_bench_top.i2c_slave);

	      // initially values
	      clk = 0;
		  instrument_clk = 0;

	      // reset system
	      rstn = 1'b1; // negate reset
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

	      #2;
	      rstn = 1'b0; // assert reset
	      repeat(1) @(posedge clk);
	      rstn = 1'b1; // negate reset

	      $display("status: %t done reset", $time);

	      @(posedge clk);

	      //
	      // program core
	      //

	      // program internal registers
	      u0.wb_write(1, PRER_LO, 8'hfa); // load prescaler lo-byte
	      u0.wb_write(1, PRER_LO, 8'hc8); // load prescaler lo-byte
	      u0.wb_write(1, PRER_HI, 8'h00); // load prescaler hi-byte
	      $display("status: %t programmed registers", $time);

	      u0.wb_cmp(0, PRER_LO, 8'hc8); // verify prescaler lo-byte
	      u0.wb_cmp(0, PRER_HI, 8'h00); // verify prescaler hi-byte
	      $display("status: %t verified registers", $time);

	      u0.wb_write(1, CTR,     8'h80); // enable core
	      $display("status: %t core enabled", $time);

	      //
	      // access slave (write)
	      //

	      // drive slave address
	      u0.wb_write(1, TXR, {SADR,WR} ); // present slave address, set write-bit
	      u0.wb_write(0, CR,      8'h90 ); // set command (start, write)
	      $display("status: %t generate 'start', write cmd %0h (slave address+write)", $time, {SADR,WR} );

	      // check tip bit
	      u0.wb_read(1, SR, q);
	      while(q[1])
	           u0.wb_read(0, SR, q); // poll it until it is zero
	      $display("status: %t tip==0", $time);

	      // send memory address
	      u0.wb_write(1, TXR,     8'h01); // present slave's memory address
	      u0.wb_write(0, CR,      8'h10); // set command (write)
	      $display("status: %t write slave memory address 01", $time);

	      // check tip bit
	      u0.wb_read(1, SR, q);
	      while(q[1])
	           u0.wb_read(0, SR, q); // poll it until it is zero
	      $display("status: %t tip==0", $time);

	      // send memory contents
	      u0.wb_write(1, TXR,     8'ha5); // present data
	      u0.wb_write(0, CR,      8'h10); // set command (write)
	      $display("status: %t write data a5", $time);

while (scl) #1;
force scl= 1'b0;
#100000;
release scl;

	      // check tip bit
	      u0.wb_read(1, SR, q);
	      while(q[1])
	           u0.wb_read(1, SR, q); // poll it until it is zero
	      $display("status: %t tip==0", $time);

	      // send memory contents for next memory address (auto_inc)
	      u0.wb_write(1, TXR,     8'h5a); // present data
	      u0.wb_write(0, CR,      8'h50); // set command (stop, write)
	      $display("status: %t write next data 5a, generate 'stop'", $time);

	      // check tip bit
	      u0.wb_read(1, SR, q);
	      while(q[1])
	           u0.wb_read(1, SR, q); // poll it until it is zero
	      $display("status: %t tip==0", $time);

	      //
	      // delay
	      //
//	      #100000; // wait for 100us.
//	      $display("status: %t wait 100us", $time);

	      //
	      // access slave (read)
	      //

	      // drive slave address
	      u0.wb_write(1, TXR,{SADR,WR} ); // present slave address, set write-bit
	      u0.wb_write(0, CR,     8'h90 ); // set command (start, write)
	      $display("status: %t generate 'start', write cmd %0h (slave address+write)", $time, {SADR,WR} );

	      // check tip bit
	      u0.wb_read(1, SR, q);
	      while(q[1])
	           u0.wb_read(1, SR, q); // poll it until it is zero
	      $display("status: %t tip==0", $time);

	      // send memory address
	      u0.wb_write(1, TXR,     8'h01); // present slave's memory address
	      u0.wb_write(0, CR,      8'h10); // set command (write)
	      $display("status: %t write slave address 01", $time);

	      // check tip bit
	      u0.wb_read(1, SR, q);
	      while(q[1])
	           u0.wb_read(1, SR, q); // poll it until it is zero
	      $display("status: %t tip==0", $time);

	      // drive slave address
	      u0.wb_write(1, TXR, {SADR,RD} ); // present slave's address, set read-bit
	      u0.wb_write(0, CR,      8'h90 ); // set command (start, write)
	      $display("status: %t generate 'repeated start', write cmd %0h (slave address+read)", $time, {SADR,RD} );

	      // check tip bit
	      u0.wb_read(1, SR, q);
	      while(q[1])
	           u0.wb_read(1, SR, q); // poll it until it is zero
	      $display("status: %t tip==0", $time);

	      // read data from slave
	      u0.wb_write(1, CR,      8'h20); // set command (read, ack_read)
	      $display("status: %t read + ack", $time);

	      // check tip bit
	      u0.wb_read(1, SR, q);
	      while(q[1])
	           u0.wb_read(1, SR, q); // poll it until it is zero
	      $display("status: %t tip==0", $time);

	      // check data just received
	      u0.wb_read(1, RXR, qq);
	      if(qq !== 8'ha5)
	        $display("\nERROR: Expected a5, received %x at time %t", qq, $time);
	      else
	        $display("status: %t received %x", $time, qq);

	      // read data from slave
	      u0.wb_write(1, CR,      8'h20); // set command (read, ack_read)
	      $display("status: %t read + ack", $time);

	      // check tip bit
	      u0.wb_read(1, SR, q);
	      while(q[1])
	           u0.wb_read(1, SR, q); // poll it until it is zero
	      $display("status: %t tip==0", $time);

	      // check data just received
	      u0.wb_read(1, RXR, qq);
	      if(qq !== 8'h5a)
	        $display("\nERROR: Expected 5a, received %x at time %t", qq, $time);
	      else
	        $display("status: %t received %x", $time, qq);

	      // read data from slave
	      u0.wb_write(1, CR,      8'h20); // set command (read, ack_read)
	      $display("status: %t read + ack", $time);

	      // check tip bit
	      u0.wb_read(1, SR, q);
	      while(q[1])
	           u0.wb_read(1, SR, q); // poll it until it is zero
	      $display("status: %t tip==0", $time);

	      // check data just received
	      u0.wb_read(1, RXR, qq);
	      $display("status: %t received %x from 3rd read address", $time, qq);

	      // read data from slave
	      u0.wb_write(1, CR,      8'h28); // set command (read, nack_read)
	      $display("status: %t read + nack", $time);

	      // check tip bit
	      u0.wb_read(1, SR, q);
	      while(q[1])
	           u0.wb_read(1, SR, q); // poll it until it is zero
	      $display("status: %t tip==0", $time);

	      // check data just received
	      u0.wb_read(1, RXR, qq);
	      $display("status: %t received %x from 4th read address", $time, qq);

	      //
	      // check invalid slave memory address
	      //

	      // drive slave address
	      u0.wb_write(1, TXR, {SADR,WR} ); // present slave address, set write-bit
	      u0.wb_write(0, CR,      8'h90 ); // set command (start, write)
	      $display("status: %t generate 'start', write cmd %0h (slave address+write). Check invalid address", $time, {SADR,WR} );

	      // check tip bit
	      u0.wb_read(1, SR, q);
	      while(q[1])
	           u0.wb_read(1, SR, q); // poll it until it is zero
	      $display("status: %t tip==0", $time);

	      // send memory address
	      u0.wb_write(1, TXR,     8'h10); // present slave's memory address
	      u0.wb_write(0, CR,      8'h10); // set command (write)
	      $display("status: %t write slave memory address 10", $time);

	      // check tip bit
	      u0.wb_read(1, SR, q);
	      while(q[1])
	           u0.wb_read(1, SR, q); // poll it until it is zero
	      $display("status: %t tip==0", $time);

	      // slave should have send NACK
	      $display("status: %t Check for nack", $time);
	      if(!q[7])
	        $display("\nERROR: Expected NACK, received ACK\n");

	      // read data from slave
	      u0.wb_write(1, CR,      8'h40); // set command (stop)
	      $display("status: %t generate 'stop'", $time);

	      // check tip bit
	      u0.wb_read(1, SR, q);
	      while(q[1])
	      u0.wb_read(1, SR, q); // poll it until it is zero
	      $display("status: %t tip==0", $time);

	      // #250000; // wait 250us
	      $display("\n\nstatus: %t Testbench done", $time);
		  $fclose(f);
	      $finish;
	  end

initial begin
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

#2000000
$finish;
end


// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;
        reg [7:0] rdata;
        reg [7:0] sdata;
        reg [7:0] expected;

    // 1. DECLARE VARIABLES FIRST (Top of block)





    // 2. THEN WAIT for original tests
    wait(llm_go_signal == 1);

    // 3. THEN execute logic
    $display("LLM: Starting Mutation Tests...");

    // Reset Sequence
    rstn = 1'b1;
    #10;
    rstn = 1'b0; // Assert Reset (Active Low for DUT)
    #200;
    rstn = 1'b1; // Deassert Reset
    #200;

    // ----------------------------------------------------------
    // TEST 1: Register Read/Write & Default Values
    // ----------------------------------------------------------
    $display("LLM: Test 1 - Register R/W");

    // Verify default CTR is 0x00
    u0.wb_read(1, 2, rdata); // CTR addr 2
    if (rdata !== 8'h00) $display("LLM Error: CTR default mismatch. Got %h", rdata);

    // Write/Read PRER (Prescaler)
    // Test alternating bits to catch bit-stuck faults
    u0.wb_write(1, 0, 8'h55); // PRER_LO
    u0.wb_cmp(0, 0, 8'h55);

    u0.wb_write(1, 0, 8'hAA);
    u0.wb_cmp(0, 0, 8'hAA);

    u0.wb_write(1, 1, 8'h55); // PRER_HI
    u0.wb_cmp(0, 1, 8'h55);

    // ----------------------------------------------------------
    // TEST 2: I2C Write Transaction (Master -> Slave)
    // ----------------------------------------------------------
    $display("LLM: Test 2 - I2C Write");

    // Setup Prescaler for simulation (0x00C8 = 200)
    u0.wb_write(1, 0, 8'hC8);
    u0.wb_write(1, 1, 8'h00);

    // Enable Core
    u0.wb_write(1, 2, 8'h80); // CTR = 0x80

    // Step 1: Send Slave Address + Write
    // SADR = 0x10. {SADR, WR} = 0x20.
    u0.wb_write(1, 3, 8'h20); // TXR
    u0.wb_write(1, 4, 8'h90); // CR = STA | WR

    // Wait for TIP (Transfer In Progress) to clear
    u0.wb_read(1, 4, sdata);
    while(sdata[1]) begin
        u0.wb_read(1, 4, sdata);
    end

    // Check RxACK (SR[7]). Should be 0 (ACK).
    if (sdata[7] !== 1'b0) $display("LLM Error: Address NACK received.");

    // Step 2: Send Memory Address (0x02)
    u0.wb_write(1, 3, 8'h02); // TXR
    u0.wb_write(1, 4, 8'h10); // CR = WR

    u0.wb_read(1, 4, sdata);
    while(sdata[1]) u0.wb_read(1, 4, sdata);
    if (sdata[7] !== 1'b0) $display("LLM Error: MemAddr NACK received.");

    // Step 3: Send Data (0xBE)
    u0.wb_write(1, 3, 8'hBE); // TXR
    u0.wb_write(1, 4, 8'h10); // CR = WR

    u0.wb_read(1, 4, sdata);
    while(sdata[1]) u0.wb_read(1, 4, sdata);
    if (sdata[7] !== 1'b0) $display("LLM Error: Data NACK received.");

    // Step 4: Stop
    u0.wb_write(1, 4, 8'h40); // CR = STO

    // Wait for Busy (SR[6]) to clear
    u0.wb_read(1, 4, sdata);
    while(sdata[6]) u0.wb_read(1, 4, sdata);

    // ----------------------------------------------------------
    // TEST 3: I2C Read Transaction (Slave -> Master)
    // ----------------------------------------------------------
    $display("LLM: Test 3 - I2C Read");

    // Step 1: Write Address (to set memory pointer)
    u0.wb_write(1, 3, 8'h20); // Addr + W
    u0.wb_write(1, 4, 8'h90); // STA | WR
    u0.wb_read(1, 4, sdata);
    while(sdata[1]) u0.wb_read(1, 4, sdata);

    // Step 2: Send Memory Address (0x02)
    u0.wb_write(1, 3, 8'h02); 
    u0.wb_write(1, 4, 8'h10); // WR
    u0.wb_read(1, 4, sdata);
    while(sdata[1]) u0.wb_read(1, 4, sdata);

    // Step 3: Repeated Start + Address Read
    // {SADR, RD} = 0x21
    u0.wb_write(1, 3, 8'h21); 
    u0.wb_write(1, 4, 8'h90); // STA | WR
    u0.wb_read(1, 4, sdata);
    while(sdata[1]) u0.wb_read(1, 4, sdata);

    // Step 4: Read Data + NACK (Single byte read)
    u0.wb_write(1, 4, 8'h28); // CR = RD | ACK=1 (NACK)
    u0.wb_read(1, 4, sdata);
    while(sdata[1]) u0.wb_read(1, 4, sdata);

    // Step 5: Verify Data
    u0.wb_read(1, 3, rdata); // Read RXR (Addr 3)
    if (rdata !== 8'hBE) $display("LLM Error: Read mismatch. Exp 0xBE, Got %h", rdata);

    // Step 6: Stop
    u0.wb_write(1, 4, 8'h40); // STO
    u0.wb_read(1, 4, sdata);
    while(sdata[6]) u0.wb_read(1, 4, sdata);

    // ----------------------------------------------------------
    // TEST 4: Interrupt Logic
    // ----------------------------------------------------------
    $display("LLM: Test 4 - Interrupts");

    // Enable Interrupts (IEN = Bit 6)
    u0.wb_write(1, 2, 8'hC0); // CTR = EN | IEN

    // Perform a quick Start condition (should trigger interrupt on completion)
    u0.wb_write(1, 3, 8'h20); 
    u0.wb_write(1, 4, 8'h90); // STA | WR

    u0.wb_read(1, 4, sdata);
    while(sdata[1]) u0.wb_read(1, 4, sdata);

    // Check Interrupt Signal (inta)
    #10;
    if (inta !== 1'b1) $display("LLM Error: Interrupt not asserted.");

    // Check SR[0] (IF)
    u0.wb_read(1, 4, sdata);
    if (sdata[0] !== 1'b1) $display("LLM Error: SR[0] (IF) not set.");

    // Clear Interrupt (Write 1 to IACK bit 0 of CR)
    u0.wb_write(1, 4, 8'h01); // IACK
    #10;
    if (inta !== 1'b0) $display("LLM Error: Interrupt not cleared.");

    // Disable Core
    u0.wb_write(1, 2, 8'h00);

    // 4. Cleanup
    $display("LLM Tests Finished. Handing over to Original TB...");
    llm_go_signal = 0; 
end
