      ST_IDLE: if(go) begin
        if(start) begin
          c_state <= #1 ST_START;
          core_cmd <= #1 4'b0001;
        end else if(read) begin
          c_state <= #1 ST_READ;
          core_cmd <= #1 4'b1000;
        end else if(write) begin
          c_state <= #1 ST_WRITE;
          core_cmd <= #1 4'b0100;
        end else begin
          c_state <= #1 ST_STOP;
          core_cmd <= #1 4'b0010;
        end
        ld <= #1 1'b1;
      end 
      ST_START: if(core_ack) begin
        if(read) begin
          c_state <= #1 ST_READ;
          core_cmd <= #1 4'b1000;
        end else begin
          c_state <= #1 ST_WRITE;
          core_cmd <= #1 4'b0100;
        end
        ld <= #1 1'b1;
      end 
      ST_WRITE: if(core_ack) if(cnt_done) begin
        c_state <= #1 ST_ACK;
        core_cmd <= #1 4'b1000;
      end else begin
        c_state <= #1 ST_WRITE;
        core_cmd <= #1 4'b0100;
        shift <= #1 1'b1;
      end 
      ST_READ: if(core_ack) begin
        if(cnt_done) begin
          c_state <= #1 ST_ACK;
          core_cmd <= #1 4'b0100;
        end else begin
          c_state <= #1 ST_READ;
          core_cmd <= #1 4'b1000;
        end
        shift <= #1 1'b1;
        core_txd <= #1 ack_in;
      end 
      ST_ACK: if(core_ack) begin
        if(stop) begin
          c_state <= #1 ST_STOP[1];
          core_cmd <= #1 4'b0010;
        end else begin
          c_state <= #1 ST_IDLE;
          core_cmd <= #1 4'b0000;
          cmd_ack <= #1 1'b1;
        end
